import { defineStore } from "pinia";

export const useGlobalsStore = defineStore("globals", {
  state: () => {
    return {
      devMode: process.env.NODE_ENV === "development" ? true : false,
      isMainMenuOpen: false,
    };
  },
  actions: {
    exampleAction() {
      this.devMode = false;
    },
  },
});
