<template>
  <div v-if="screenshots">
    <Button @click="refreshHandler" :disabled="isLoading">Refresh</Button>
    <div class="Screenshots grid gap-3 grid-cols-3 mt-3">
      <Card
        v-for="file in screenshots"
        :key="file"
        @click="ssClickHandler(file)"
        style="height: 250px; width: 100%"
        :style="{
          background: `url(https://phpscreenshotserver.ls-cc.info/screenshots/${file.name}) center / cover no-repeat`,
        }"
      >
      </Card>
    </div>
  </div>
</template>

<script>
import axios from "axios";
import Button from "../../../components/Button.vue";
import moment from "moment";
import Card from "../../../components/Card.vue";

export default {
  name: "ScreenshotsTab",
  components: { Button, Card },
  data() {
    return {
      screenshots: [],
      isLoading: true,
    };
  },
  methods: {
    ssClickHandler(ss) {
      global.Modal.fire({
        imageUrl: `https://phpscreenshotserver.ls-cc.info/screenshots/${ss.name}`,
        width: 1000,
        imageAlt: ss.name,
        confirmButtonText: "Close",
        padding: "1em",
        html: `
        <div class="flex justify-center">
            <div class="flex flex-col items-start">
                <div><strong>Player:</strong> ${ss.user}</div>
                <div><strong>Admin:</strong> ${ss.admin}</div>
                <div><strong>Date:</strong> ${moment(ss.date).format(
                  "MMMM Do YYYY, h:mm:ss A"
                )}</div>
            </div>
        </div>
        `,
      });
    },
    refreshHandler() {
      if (this.isLoading) return;
      this.getScreenshots(true);
    },
    getScreenshots(ann = false) {
      let that = this;
      that.isLoading = true;
      let oldSS = that.screenshots.length;
      axios
        .get("http://193.70.88.74:8237/ss/list")
        .then(function (response) {
          let arr = response.data.map((file) => ({
            name: file.name,
            user: file.name.split(";")[0],
            admin: file.name.split(";adm_").pop().split("+")[0],
            date: file.date,
            size: file.size,
          }));
          that.screenshots = arr;
          that.isLoading = false;

          if (ann)
            global.Toast.fire({
              icon: "success",
              title: "Refreshed",
              text:
                arr.length > oldSS
                  ? `Loaded ${arr.length - oldSS} new screenshots!`
                  : false,
            });
        })
        .catch(function (error) {
          console.log(error);
          that.isLoading = false;
        });
    },
  },
  created() {
    this.getScreenshots();
  },
};
</script>

<style scoped lang="scss">
* {
  color: $white-text;
}

.Screenshots {
  max-height: 700px;
  overflow-y: scroll;
  height: 100%;
  padding-right: 5px;
  border-radius: $radius-md;
}
</style>
